"""
Module for extracting alarms from IMS2 logs and verify if alarm was set or removed in passed timeframe.
Sample robot usage:

*** Settings ***
Library    taf.ul.alarms_watchdog.interface.alarms_watchdog                     WITH NAME    awd
Library    taf.rfrl.common_resources.python.ims2_alarms.IMS2AlarmVerifier       WITH NAME    iav


*** Test Cases ***
TEST COMMON RESOURCE
    ${wanted_alarm}    awd.create_alarm    alarm_id=1234    fault_id=5678    severity=Minor
    iav.set start timestamp
    # Perform an operation that causes an alarm to appear.
    ## Maybe some 'sleep' will be needed?
    iav.set end timestamp
    # ${ims_path1}    download IMS2
    ${detected_alarm}    iav.verify alarm was set    alarm=${wanted_alarm}    ims_file_path=${ims_path1}

    iav.set start timestamp
    # Perform an operation that causes an alarm to disappear.
    ## Maybe some 'sleep' will be needed?
    iav.set end timestamp
    # ${ims_path2}    download IMS2
    iav.verify alarm was removed    alarm_dist_name=${detected_alarm['dist_name']}    ims_file_path=${ims_path2}
"""
import logging
import pytz
import re
from datetime import datetime
from dateutil import parser
from dateutil.parser import ParserError
from taf.analyzer.ims2 import Ims2ChangesetLogEntry, Ims2LogReader
from taf.ul.alarms_watchdog import Alarm


class IMS2AlarmExtractor:
    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'
    ALARM_REGEX = r'/MRBTS-\d+/RAT-\d+/FRI-\d+/ALARM-\d+$'
    FAULT_NOTIF_REGEX = r'/MRBTS-\d+/RAT-\d+/FRI-\d+/FAULT_NOTIF-\d+$'

    def __init__(self):
        self.search_start_timestamp = None
        self.search_end_timestamp = None
        self._compiled_alarm_regex = re.compile(IMS2AlarmExtractor.ALARM_REGEX)
        self._compiled_fault_regex = re.compile(IMS2AlarmExtractor.FAULT_NOTIF_REGEX)

    def set_start_timestamp(self, time=None):
        """
        Save start timestamp. Only IMS records >= are taken to parser.
        :param datetime, str time: Optional - if not passed current time is used. You can pass as datetime object or
                as string in ISO format eg: '2022-05-19T12:00:15.699000'
        :return: None
        """
        if time is None:
            self.search_start_timestamp = self._get_current_utc_time()
        else:
            self.search_start_timestamp = self._get_timestamp_in_datetime_format(time)

        logging.debug(f"Start timestamp set to: {self.search_start_timestamp}")

    def set_end_timestamp(self, time=None):
        """
        Save end timestamp. Only IMS records <= are taken to parser.
        :param datetime, str time: Optional - if not passed current time is used. Ypu can pass as datetime object or
                as string in ISO format eg: '2022-05-19T12:00:15.699000'
        :return: None
        """
        if time is None:
            self.search_end_timestamp = self._get_current_utc_time()
        else:
            self.search_end_timestamp = self._get_timestamp_in_datetime_format(time)

        logging.debug(f"End timestamp set to: {self.search_end_timestamp}")

    def get_alarms_set_in_passed_timeframe(self, ims_file_path, start=None, end=None, visible_for_EM=None,
                                           compare_using_observation_time=False, include_fault_notif=False):
        """
        Get alarms set in passed timeframe.
        :param str ims_file_path: Path to IMS2 log file
        :param datetime, str start: Optional - start time for search. If not passed, start time is taken from
                set_start_timestamp method
        :param datetime, str end: Optional - end time for search. If not passed, end time is taken from
                set_end_timestamp method
        :param bool visible_for_EM: Optional - If None, it does not matter if the alarm is visible for EM or not.
                                               If True, filter to alarms visible for EM.
                                               If False, filter to alarms not visible for EM.
        :param bool compare_using_observation_time: Optional -  If True, compare alarms using observation time.
                                                                If False, use frame timestamp.
        :param bool include_fault_notif: Optional - If True, include fault notifications in the result.
        return: list of dict with dist_name, timestamp and alarm object
        """
        alarms = []
        log_entries_in_timeframe = self._get_ims_log_entry_in_passed_timeframe(ims_file_path, start, end,
                                                                               compare_using_observation_time)
        for frame_number, log_entry in log_entries_in_timeframe:
            for dist_name, value in log_entry.updates.items():
                if self._compiled_alarm_regex.search(dist_name):
                    alarm_filter = True if visible_for_EM is None else value["visibleForEM"] is visible_for_EM
                    if not alarm_filter:
                        continue
                    logging.info(f"[{frame_number}][{log_entry.timestamp}] Alarm detected under {dist_name}")
                    self._append_alarm_to_list(alarms, dist_name, value)
                    logging.debug(alarms[-1])
                elif include_fault_notif and self._compiled_fault_regex.search(dist_name):
                    logging.info(f"[{frame_number}][{log_entry.timestamp}] Fault detected under {dist_name}")
                    self._append_fault_to_list(alarms, dist_name, value, log_entry.timestamp)
                    logging.debug(alarms[-1])

        return alarms

    def _append_alarm_to_list(self, alarms, dist_name, value):
        alarm = Alarm(
            alarm_id=value.get('alarmNumber'),
            fault_id=value.get('faultId'),
            fault_name=value.get('alarmText')['faultDescription'],
            severity=value.get('alarmSeverity'),
            unit_path=value.get('alarmingResourceDN'))
        alarms.append(
            {
                "object": alarm,
                "dist_name": dist_name,
                "observation_time": self._get_timestamp_in_datetime_format(value["observationTime"]),
                "visible_for_EM": value["visibleForEM"],
                "visible_for_NetAct": value["visibleForNetAct"],
                "visible_for_Onap": value["visibleForOnap"],
            }
        )

    def _append_fault_to_list(self, alarms, dist_name, value, timestamp):
        fault = Alarm(
            fault_id=value.get('faultId'),
            fault_name=value.get('faultName'),
            severity=value.get('faultSeverity'),
            unit_path=value.get('faultyObject'))
        alarms.append(
            {
                "object": fault,
                "dist_name": dist_name,
                "timestamp": timestamp,
            }
        )

    def get_alarms_removed_in_passed_timeframe(self, ims_file_path, start=None, end=None, include_fault_notif=False):
        """
        Get alarms removed in passed timeframe.
        :param str ims_file_path: Path to IMS2 log file
        :param datetime, str start: Optional - start time for search. If not passed, start time is taken from
                set_start_timestamp method
        :param datetime, str end: Optional - end time for search. If not passed, end time is taken from
                set_end_timestamp method
        :param bool include_fault_notif: Optional - If True, include fault notifications in the result.
        return: list of dict with dist_name and timestamp
        """
        alarm_dist_names = []
        log_entries_in_timeframe = self._get_ims_log_entry_in_passed_timeframe(ims_file_path, start, end)
        for frame_number, log_entry in log_entries_in_timeframe:
            for dist_name in log_entry.removals:
                if (self._compiled_alarm_regex.search(dist_name)
                        or (include_fault_notif and self._compiled_fault_regex.search(dist_name))):
                    alarm_dist_names.append({
                        'dist_name': dist_name,
                        'timestamp': log_entry.timestamp
                    })
        return alarm_dist_names

    def _get_ims_log_entry_in_passed_timeframe(self, ims_file_path, search_start_timestamp=None,
                                               search_end_timestamp=None, compare_using_observation_time=False):
        search_start_timestamp = self.search_start_timestamp if search_start_timestamp is None \
            else search_start_timestamp
        search_end_timestamp = self.search_end_timestamp if search_end_timestamp is None else search_end_timestamp

        if compare_using_observation_time:
            return self._filter_by_observation_time(ims_file_path, search_start_timestamp, search_end_timestamp)
        else:
            return self._filter_by_timeframe(ims_file_path, search_start_timestamp, search_end_timestamp)

    def _filter_by_timeframe(self, ims_file_path, search_start_timestamp=None, search_end_timestamp=None):
        for frame_number, log_entry in self._get_ims_change_log_entry_entry(ims_file_path):
            if self._is_entry_in_time_range(log_entry.timestamp, search_start_timestamp, search_end_timestamp):
                yield frame_number, log_entry

    def _filter_by_observation_time(self, ims_file_path, search_start_timestamp=None, search_end_timestamp=None):
        for frame_number, log_entry in self._get_ims_change_log_entry_entry(ims_file_path):
            for dist_name, value in log_entry.updates.items():
                if 'observationTime' in value:
                    observation_timestamp = self._get_timestamp_in_datetime_format(value["observationTime"])
                    if self._is_entry_in_time_range(observation_timestamp,
                                                    search_start_timestamp, search_end_timestamp):
                        yield frame_number, log_entry

    @staticmethod
    def _get_ims_change_log_entry_entry(ims_file_path):
        logging.debug("Start processing: {}".format(ims_file_path))
        for frame_number, log_entry in enumerate(Ims2LogReader.from_file(file_path=ims_file_path)):
            if isinstance(log_entry, Ims2ChangesetLogEntry):
                yield frame_number, log_entry

    @staticmethod
    def is_alarm_in_time_range(start, end, alarm):
        if start is None and end is None:
            return True
        elif start is None and alarm.alarm_set_timestamp <= end:
            return True
        elif end is None and (alarm.alarm_removed_timestamp is None or alarm.alarm_removed_timestamp >= start):
            return True
        elif start and end and alarm.alarm_set_timestamp <= end and \
                (alarm.alarm_removed_timestamp is None or alarm.alarm_removed_timestamp >= start):
            return True
        return False

    @staticmethod
    def _is_entry_in_time_range(current_time, start, end):
        """
        Check if current time fall in range between star and end
        :param datetime current_time: Current time from IMS log
        :param datetime start: defined start time
        :param datetime end:  defined end time
        :return bool: True/False
        """
        if not start and not end:
            return True
        elif not start and end and current_time <= end:
            return True
        elif start and not end and current_time >= start:
            return True
        elif start and end and start <= current_time <= end:
            return True

        return False

    @staticmethod
    def _get_timestamp_in_datetime_format(timestamp):
        if not isinstance(timestamp, datetime):
            if ':' not in timestamp:
                parsed_timestamp = datetime.strptime(timestamp, "%Y%m%d%H%M%S.%f%z")
            else:
                try:
                    timestamp_with_z_postfix = "{}Z".format(timestamp)
                    parsed_timestamp = parser.parse(timestamp_with_z_postfix)
                except ParserError:
                    parsed_timestamp = parser.parse(timestamp)
        else:
            parsed_timestamp = timestamp

        return parsed_timestamp

    @staticmethod
    def _get_current_utc_time():
        return datetime.now(pytz.utc)


class IMS2AlarmVerifier(IMS2AlarmExtractor):

    def was_alarm_set(self, alarm, ims_file_path, start=None, end=None, visible_for_EM=None,
                      compare_using_observation_time=False, include_fault_notif=False):
        """
        Check if alarm was set in passed timeframe.
        :param Alarm alarm: Alarm object from taf.ul.alarms_watchdog
        :param str ims_file_path: Path to IMS2 log file
        :param datetime, str start: Optional - start time for search. If not passed, start time is taken from
                set_start_timestamp method
        :param datetime, str end: Optional - end time for search. If not passed, end time is taken from
                set_end_timestamp method
        :param bool visible_for_EM: Optional - If None, it does not matter if the alarm is visible for EM or not.
                                               If True, filter to alarms visible for EM.
                                               If False, filter to alarms not visible for EM.
        :param bool compare_using_observation_time: Optional -  If True, compare alarms using observation time.
                                                                If False, use frame timestamp.
        :param bool include_fault_notif: Optional - If True, include fault notifications in the result.
        """
        all_detected_alarms = self.get_alarms_set_in_passed_timeframe(ims_file_path, start, end, visible_for_EM,
                                                                      compare_using_observation_time,
                                                                      include_fault_notif)
        for detected_alarm in all_detected_alarms:
            if alarm == detected_alarm['object']:
                logging.debug(f"Detected alarm {detected_alarm} was set in passed timeframe")
                return detected_alarm
        return None

    def verify_alarm_was_set(self, alarm, ims_file_path, start=None, end=None, visible_for_EM=None,
                             compare_using_observation_time=False, include_fault_notif=False):
        """
        Verify if alarm was set in passed timeframe. If not - raise AssertionError.
        :param Alarm alarm: Alarm object from taf.ul.alarms_watchdog
        :param str ims_file_path: Path to IMS2 log file
        :param datetime, str start: Optional - start time for search. If not passed, start time is taken from
                set_start_timestamp method
        :param datetime, str end: Optional - end time for search. If not passed, end time is taken from
                set_end_timestamp method
        :param bool visible_for_EM: Optional - If None, it does not matter if the alarm is visible for EM or not.
                                               If True, filter to alarms visible for EM.
                                               If False, filter to alarms not visible for EM.
        :param bool compare_using_observation_time: Optional -  If True, compare alarms using observation time.
                                                                If False, use frame timestamp.
        :param bool include_fault_notif: Optional - If True, include fault notifications in the result.
        """
        detected_alarm = self.was_alarm_set(alarm, ims_file_path, start, end, visible_for_EM,
                                            compare_using_observation_time, include_fault_notif)
        if detected_alarm is None:
            raise AssertionError(f"Alarm {alarm} was not set in passed timeframe")
        return detected_alarm

    def were_alarms_set(self, alarms, ims_file_path, start=None, end=None, visible_for_EM=None,
                        compare_using_observation_time=False, include_fault_notif=False):
        """
        Check if all alarms from list were set in passed timeframe.
        :param list alarms: List of Alarm objects from taf.ul.alarms_watchdog
        :param str ims_file_path: Path to IMS2 log file
        :param datetime, str start: Optional - start time for search. If not passed, start time is taken from
                set_start_timestamp method
        :param datetime, str end: Optional - end time for search. If not passed, end time is taken from
                set_end_timestamp method
        :param bool visible_for_EM: Optional - If None, it does not matter if the alarm is visible for EM or not.
                                               If True, filter to alarms visible for EM.
                                               If False, filter to alarms not visible for EM.
        :param bool compare_using_observation_time: Optional -  If True, compare alarms using observation time.
                                                                If False, use frame timestamp.
        :param bool include_fault_notif: Optional - If True, include fault notifications in the result.
        """
        detected_wanted_alarms = []
        all_detected_alarms = self.get_alarms_set_in_passed_timeframe(ims_file_path, start, end, visible_for_EM,
                                                                      compare_using_observation_time,
                                                                      include_fault_notif)
        for detected_alarm in all_detected_alarms:
            if detected_alarm['object'] in alarms:
                detected_wanted_alarms.append(detected_alarm)

        logging.debug(f"Detected alarms: {detected_wanted_alarms}")
        if len(detected_wanted_alarms) == 0:
            logging.debug("No alarms from list were set in passed timeframe")
        elif len(detected_wanted_alarms) == len(alarms):
            logging.debug("All alarms from list were set in passed timeframe")
            return detected_wanted_alarms
        else:
            logging.debug(f"Only {len(detected_wanted_alarms)} alarms from list were set in passed timeframe")
            detected_wanted_alarms_objects = [_alarm['object'] for _alarm in detected_wanted_alarms]
            missed_alarms = [alarm for alarm in alarms if alarm not in detected_wanted_alarms_objects]
            logging.debug("Missed alarms: {}".format(missed_alarms))
        return None

    def verify_alarms_were_set(self, alarms, ims_file_path, start=None, end=None, visible_for_EM=None,
                               compare_using_observation_time=False, include_fault_notif=False):
        """
        Verify if all alarms from list were set in passed timeframe. If not - raise AssertionError.
        :param list alarms: List of Alarm objects from taf.ul.alarms_watchdog
        :param str ims_file_path: Path to IMS2 log file
        :param datetime, str start: Optional - start time for search. If not passed, start time is taken from
                set_start_timestamp method
        :param datetime, str end: Optional - end time for search. If not passed, end time is taken from
                set_end_timestamp method
        :param bool visible_for_EM: Optional - If None, it does not matter if the alarm is visible for EM or not.
                                               If True, filter to alarms visible for EM.
                                               If False, filter to alarms not visible for EM.
        :param bool compare_using_observation_time: Optional -  If True, compare alarms using observation time.
                                                                If False, use frame timestamp.
        :param bool include_fault_notif: Optional - If True, include fault notifications in the result.
        """
        detected_wanted_alarms = self.were_alarms_set(alarms, ims_file_path, start, end, visible_for_EM,
                                                      compare_using_observation_time, include_fault_notif)
        if detected_wanted_alarms is None:
            raise AssertionError(f"Alarms {alarms} were not set in passed timeframe")
        return detected_wanted_alarms

    def was_alarm_removed(self, alarm_dist_name, ims_file_path, start=None, end=None, include_fault_notif=False):
        """
        Check if alarm was removed in passed timeframe.
        :param str alarm_dist_name: Alarm dist_name
        :param str ims_file_path: Path to IMS2 log file
        :param datetime, str start: Optional - start time for search. If not passed, start time is taken from
                set_start_timestamp method
        :param datetime, str end: Optional - end time for search. If not passed, end time is taken from
                set_end_timestamp method
        :param bool include_fault_notif: Optional - If True, include fault notifications in the result.
        """
        removed_alarms = self.get_alarms_removed_in_passed_timeframe(ims_file_path, start, end, include_fault_notif)
        removed_alarms_dn = [removed_alarm['dist_name'] for removed_alarm in removed_alarms]
        if alarm_dist_name in removed_alarms_dn:
            logging.debug(f"Alarm {alarm_dist_name} was removed in passed timeframe")
            return True
        return False

    def verify_alarm_was_removed(self, alarm_dist_name, ims_file_path, start=None, end=None, include_fault_notif=False):
        """
        Verify if alarm was removed in passed timeframe. If not - raise AssertionError.
                :param str alarm_dist_name: Alarm dist_name
        :param str ims_file_path: Path to IMS2 log file
        :param datetime, str start: Optional - start time for search. If not passed, start time is taken from
                set_start_timestamp method
        :param datetime, str end: Optional - end time for search. If not passed, end time is taken from
                set_end_timestamp method
        :param bool include_fault_notif: Optional - If True, include fault notifications in the result.
        """
        if not self.was_alarm_removed(alarm_dist_name, ims_file_path, start, end, include_fault_notif):
            raise AssertionError(f"Alarm {alarm_dist_name} was not removed in passed timeframe")

    def were_alarms_removed(self, alarm_dist_names, ims_file_path, start=None, end=None, include_fault_notif=False):
        """
        Check if all alarms from list were removed in passed timeframe.
        :param list alarm_dist_names: List of alarm dist_names
                :param str ims_file_path: Path to IMS2 log file
        :param datetime, str start: Optional - start time for search. If not passed, start time is taken from
                set_start_timestamp method
        :param datetime, str end: Optional - end time for search. If not passed, end time is taken from
                set_end_timestamp method
        :param bool include_fault_notif: Optional - If True, include fault notifications in the result.
        """
        removed_alarms = self.get_alarms_removed_in_passed_timeframe(ims_file_path, start, end, include_fault_notif)
        removed_alarms_dn = [removed_alarm['dist_name'] for removed_alarm in removed_alarms]
        removed_wanted_alarms = [wanted_dn for wanted_dn in alarm_dist_names if wanted_dn in removed_alarms_dn]
        logging.debug(f"Removed alarms: {removed_wanted_alarms}")
        if len(removed_wanted_alarms) == 0:
            logging.debug("No alarms from list were removed in passed timeframe")
        elif len(removed_wanted_alarms) == len(alarm_dist_names):
            logging.debug("All alarms from list were removed in passed timeframe")
            return True
        else:
            logging.debug(f"Only {len(removed_wanted_alarms)} alarms from list were removed in passed timeframe")
            missed_alarms = [alarm_dn for alarm_dn in alarm_dist_names if alarm_dn not in removed_wanted_alarms]
            logging.debug("Missed removed alarms: {}".format(missed_alarms))
        return False

    def verify_alarms_were_removed(self, alarm_dist_names, ims_file_path, start=None, end=None,
                                   include_fault_notif=False):
        """
        Verify if all alarms from list were removed in passed timeframe. If not - raise AssertionError.
        :param list alarm_dist_names: List of alarm dist_names
                :param str ims_file_path: Path to IMS2 log file
        :param datetime, str start: Optional - start time for search. If not passed, start time is taken from
                set_start_timestamp method
        :param datetime, str end: Optional - end time for search. If not passed, end time is taken from
                set_end_timestamp method
        :param bool include_fault_notif: Optional - If True, include fault notifications in the result.
        """
        if not self.were_alarms_removed(alarm_dist_names, ims_file_path, start, end, include_fault_notif):
            raise AssertionError(f"Alarm {alarm_dist_names} was not removed in passed timeframe")
